-- Section allocation repair, MySQL 8.0. No EF migrations.
-- Database name from the supplied dump. Change USE only if your database has another name.
USE cms_btech;
-- Run AFTER the supplied All_Fixes_V2 and Section_Department_Optional patches.
-- No college/year/branch/semester IDs are changed, guessed or replaced.
-- New student/profile primary keys are generated by their own AUTO_INCREMENT.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;

DELIMITER $$
DROP PROCEDURE IF EXISTS sp_Section_AllocationPreflight$$
CREATE PROCEDURE sp_Section_AllocationPreflight()
BEGIN
    IF DATABASE() IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Select the CMS database before running the allocation patch.';
    END IF;
    IF EXISTS (SELECT 1 FROM students WHERE admission_id IS NOT NULL GROUP BY admission_id HAVING COUNT(*) > 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Duplicate students.admission_id links exist. Resolve the real identities; no rows were merged.';
    END IF;
    IF EXISTS (SELECT 1 FROM student_section_assignments WHERE status=1 GROUP BY student_id HAVING COUNT(*) > 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A student has multiple active section assignments. Resolve the conflict before applying this patch.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE()
                   AND table_name='students' AND index_name='uq_section_student_admission') THEN
        ALTER TABLE students ADD UNIQUE KEY uq_section_student_admission(admission_id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE()
                   AND table_name='student_section_assignments' AND column_name='allocation_active_student_id') THEN
        ALTER TABLE student_section_assignments ADD COLUMN allocation_active_student_id BIGINT
          GENERATED ALWAYS AS (CASE WHEN status=1 THEN student_id ELSE NULL END) STORED;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE()
                   AND table_name='student_section_assignments' AND index_name='uq_section_one_active_student') THEN
        ALTER TABLE student_section_assignments ADD UNIQUE KEY uq_section_one_active_student(allocation_active_student_id);
    END IF;
END$$
CALL sp_Section_AllocationPreflight()$$
DROP PROCEDURE sp_Section_AllocationPreflight$$
DELIMITER ;

-- The faculty master owns the college relationship. A nullable users.college_id
-- never grants access to another college: the faculty row must match exactly.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW vw_section_active_faculty AS
SELECT f.faculty_id, f.college_id, ep.employee_profile_id,
       u.user_id, u.employee_user_id, u.full_name,
       d.department_name, COALESCE(f.designation,ep.designation) AS designation,
       u.email, u.mobile
FROM faculty f
JOIN employee_profiles ep ON ep.employee_profile_id=f.employee_profile_id AND ep.user_id=f.user_id
JOIN users u ON u.user_id=ep.user_id
JOIN colleges c ON c.college_id=f.college_id AND c.status=1 AND c.deleted_at IS NULL
LEFT JOIN departments d ON d.department_id=f.department_id AND d.college_id=f.college_id AND d.deleted_at IS NULL
WHERE f.status=1 AND f.deleted_at IS NULL AND ep.status=1 AND ep.deleted_at IS NULL
  AND u.status=1 AND u.deleted_at IS NULL
  AND (u.college_id IS NULL OR u.college_id=f.college_id);

-- Approved/admitted records with a real, internally consistent academic context.
-- A recorded SectionId can supply missing context only when it is consistent.
-- Draft/submitted/rejected admissions and invalid explicit semester IDs are excluded.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW vw_section_admission_mapping AS
SELECT a.AdmissionId, a.AdmissionNo, a.RegistrationNo, a.FirstName, a.LastName,
       a.Gender, a.DateOfBirth, a.StudentEmail, a.Email, a.MobileNumber, a.BloodGroup, a.Address,
       a.CreatedBy, a.UpdatedBy,
       c.college_id, co.course_id, b.branch_id, ay.academic_year_id,
       COALESCE(NULLIF(TRIM(a.AdmissionNo),''),NULLIF(TRIM(a.RegistrationNo),'')) AS student_code
FROM studentadmissions a
LEFT JOIN sections sec ON sec.section_id=a.SectionId AND sec.deleted_at IS NULL AND sec.status=1 AND sec.is_archived=0
JOIN colleges c ON c.college_id=COALESCE(a.AcademicCollegeId,sec.college_id) AND c.status=1 AND c.deleted_at IS NULL
JOIN courses co ON co.course_id=COALESCE(a.AcademicCourseId,sec.course_id) AND co.college_id=c.college_id AND co.status=1 AND co.deleted_at IS NULL
JOIN branches b ON b.branch_id=COALESCE(a.AcademicBranchId,sec.branch_id) AND b.course_id=co.course_id AND b.status=1 AND b.deleted_at IS NULL
JOIN academicyears ay ON ay.academic_year_id=COALESCE(a.AcademicYearId,sec.academic_year_id) AND ay.deleted_at IS NULL
WHERE a.IsActive=1 AND a.IsDeleted=0 AND a.AdmissionStatus IN ('Approved','Admitted')
  AND NULLIF(TRIM(a.FirstName),'') IS NOT NULL
  AND COALESCE(NULLIF(TRIM(a.AdmissionNo),''),NULLIF(TRIM(a.RegistrationNo),'')) IS NOT NULL
  AND (a.SectionId IS NULL OR (sec.college_id=c.college_id AND sec.course_id=co.course_id
       AND sec.branch_id=b.branch_id AND sec.academic_year_id=ay.academic_year_id))
  AND (a.AcademicSemesterId IS NULL OR EXISTS (
       SELECT 1 FROM semesters sem WHERE sem.semester_id=a.AcademicSemesterId
       AND sem.course_id=co.course_id AND sem.branch_id=b.branch_id AND sem.academic_year_id=ay.academic_year_id
       AND sem.status=1 AND sem.is_archived=0
       AND (a.SectionId IS NULL OR sec.semester_id=sem.semester_id)));

-- Current student-master mapping remains authoritative after promotions.
-- A known current semester is checked; missing legacy semester data is NOT
-- replaced with semester 1, a section ID, or an admission ID. The existing
-- allocation contract requires college/course/branch/year, not a new semester field.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW vw_section_student_academics AS
SELECT st.student_id, st.admission_id, st.student_code, st.full_name, st.email, st.mobile,
       st.college_id, st.course_id, st.branch_id, st.academic_year_id,
       CASE WHEN pr.promotion_id IS NOT NULL THEN pr.to_semester_id
            WHEN a.AcademicCollegeId=st.college_id AND a.AcademicCourseId=st.course_id
             AND a.AcademicBranchId=st.branch_id AND a.AcademicYearId=st.academic_year_id
            THEN a.AcademicSemesterId ELSE NULL END AS semester_id,
       CASE WHEN pr.promotion_id IS NOT NULL THEN pr.to_semester ELSE NULL END AS semester_number
FROM students st
JOIN colleges c ON c.college_id=st.college_id AND c.status=1 AND c.deleted_at IS NULL
JOIN courses co ON co.course_id=st.course_id AND co.college_id=st.college_id AND co.status=1 AND co.deleted_at IS NULL
JOIN branches b ON b.branch_id=st.branch_id AND b.course_id=st.course_id AND b.status=1 AND b.deleted_at IS NULL
JOIN academicyears ay ON ay.academic_year_id=st.academic_year_id AND ay.deleted_at IS NULL
LEFT JOIN studentadmissions a ON a.AdmissionId=st.admission_id
LEFT JOIN student_promotions pr ON pr.promotion_id=(
    SELECT MAX(p.promotion_id) FROM student_promotions p
    WHERE p.student_id=st.student_id AND p.promotion_status='APPROVED' AND p.deleted_at IS NULL AND p.is_active=1)
WHERE st.status=1 AND st.deleted_at IS NULL
  AND (st.admission_id IS NULL OR (a.IsActive=1 AND a.IsDeleted=0 AND a.AdmissionStatus IN ('Approved','Admitted')))
  AND (pr.promotion_id IS NULL OR (pr.to_academic_year_id=st.academic_year_id
       AND pr.to_course_id=st.course_id AND pr.to_branch_id=st.branch_id));

-- ONE eligibility predicate for both candidate GET and transactional assignment.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW vw_section_student_eligibility AS
SELECT sec.section_id, st.*
FROM sections sec
JOIN semesters sem ON sem.semester_id=sec.semester_id AND sem.course_id=sec.course_id
 AND sem.branch_id=sec.branch_id AND sem.academic_year_id=sec.academic_year_id AND sem.status=1 AND sem.is_archived=0
JOIN vw_section_student_academics st ON st.college_id=sec.college_id
 AND st.course_id=sec.course_id AND st.branch_id=sec.branch_id AND st.academic_year_id=sec.academic_year_id
WHERE sec.status=1 AND sec.deleted_at IS NULL AND sec.is_archived=0
  AND (sec.semester IS NULL OR sec.semester=sem.semester_number)
  AND (st.semester_id IS NULL OR st.semester_id=sem.semester_id)
  AND (st.semester_number IS NULL OR st.semester_number=sem.semester_number)
  AND NOT EXISTS (SELECT 1 FROM student_section_assignments x WHERE x.student_id=st.student_id AND x.status=1)
  AND NOT EXISTS (SELECT 1 FROM student_sections x WHERE x.student_id=st.student_id AND x.is_active=1);

DELIMITER $$
-- This helper participates in the caller's transaction; it never commits.
DROP PROCEDURE IF EXISTS sp_Section_EnsureEmployeeProfile$$
CREATE PROCEDURE sp_Section_EnsureEmployeeProfile(
 IN p_user_id BIGINT, IN p_college_id BIGINT, IN p_department_id BIGINT,
 IN p_designation VARCHAR(150), IN p_actor BIGINT, OUT p_profile_id BIGINT)
main: BEGIN
    SET p_profile_id=NULL;
    IF NOT EXISTS (SELECT 1 FROM users u JOIN colleges c ON c.college_id=p_college_id
        WHERE u.user_id=p_user_id AND u.status=1 AND u.deleted_at IS NULL
          AND (u.college_id IS NULL OR u.college_id=p_college_id) AND c.status=1 AND c.deleted_at IS NULL) THEN
        LEAVE main;
    END IF;
    IF EXISTS (SELECT 1 FROM employee_profiles WHERE user_id=p_user_id) THEN
        SELECT employee_profile_id INTO p_profile_id FROM employee_profiles
        WHERE user_id=p_user_id AND status=1 AND deleted_at IS NULL;
        LEAVE main;
    END IF;
    -- Copy a department only after verifying its actual college. Never relocate faculty.
    IF p_department_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM departments
        WHERE department_id=p_department_id AND college_id=p_college_id AND deleted_at IS NULL) THEN
        LEAVE main;
    END IF;
    INSERT INTO employee_profiles(user_id,department_id,designation,status,created_at,created_by)
    VALUES(p_user_id,p_department_id,p_designation,1,UTC_TIMESTAMP(),p_actor);
    SET p_profile_id=LAST_INSERT_ID();
END$$

-- No synthetic student ID and no overwrite of existing progression/status data.
DROP PROCEDURE IF EXISTS sp_Section_MaterializeAdmissionStudent$$
CREATE PROCEDURE sp_Section_MaterializeAdmissionStudent(IN p_admission_id BIGINT)
BEGIN
    INSERT INTO students(admission_id,college_id,student_code,full_name,gender,date_of_birth,email,mobile,
                         blood_group,address,course_id,branch_id,academic_year_id,status,created_at,created_by)
    SELECT a.AdmissionId,a.college_id,a.student_code,TRIM(CONCAT_WS(' ',a.FirstName,NULLIF(TRIM(a.LastName),''))),
           a.Gender,a.DateOfBirth,COALESCE(NULLIF(TRIM(a.StudentEmail),''),a.Email),a.MobileNumber,
           a.BloodGroup,LEFT(a.Address,500),a.course_id,a.branch_id,a.academic_year_id,1,UTC_TIMESTAMP(),COALESCE(a.UpdatedBy,a.CreatedBy)
    FROM vw_section_admission_mapping a
    WHERE a.AdmissionId=p_admission_id
      AND NOT EXISTS (SELECT 1 FROM students s WHERE s.admission_id=a.AdmissionId)
      AND NOT EXISTS (SELECT 1 FROM students s WHERE s.student_code COLLATE utf8mb4_0900_ai_ci=a.student_code COLLATE utf8mb4_0900_ai_ci);
END$$

-- Cover all existing admission write endpoints, including direct status changes.
-- Candidate GETs remain read-only. Triggers run atomically with the original write.
DROP TRIGGER IF EXISTS trg_section_admission_student_ai$$
CREATE TRIGGER trg_section_admission_student_ai AFTER INSERT ON studentadmissions FOR EACH ROW
BEGIN
    CALL sp_Section_MaterializeAdmissionStudent(NEW.AdmissionId);
END$$
DROP TRIGGER IF EXISTS trg_section_admission_student_au$$
CREATE TRIGGER trg_section_admission_student_au AFTER UPDATE ON studentadmissions FOR EACH ROW
BEGIN
    CALL sp_Section_MaterializeAdmissionStudent(NEW.AdmissionId);
END$$
DROP TRIGGER IF EXISTS trg_section_faculty_profile_bi$$
CREATE TRIGGER trg_section_faculty_profile_bi BEFORE INSERT ON faculty FOR EACH ROW
BEGIN
    DECLARE v_profile_id BIGINT;
    IF NEW.employee_profile_id IS NULL AND NEW.status=1 AND NEW.deleted_at IS NULL THEN
        CALL sp_Section_EnsureEmployeeProfile(NEW.user_id,NEW.college_id,NEW.department_id,NEW.designation,NEW.created_by,v_profile_id);
        SET NEW.employee_profile_id=v_profile_id;
    END IF;
END$$
DROP TRIGGER IF EXISTS trg_section_faculty_profile_bu$$
CREATE TRIGGER trg_section_faculty_profile_bu BEFORE UPDATE ON faculty FOR EACH ROW
BEGIN
    DECLARE v_profile_id BIGINT;
    IF NEW.employee_profile_id IS NULL AND NEW.status=1 AND NEW.deleted_at IS NULL THEN
        CALL sp_Section_EnsureEmployeeProfile(NEW.user_id,NEW.college_id,NEW.department_id,NEW.designation,NEW.updated_by,v_profile_id);
        SET NEW.employee_profile_id=v_profile_id;
    END IF;
END$$

DROP PROCEDURE IF EXISTS sp_Section_BackfillAllocationLinks$$
CREATE PROCEDURE sp_Section_BackfillAllocationLinks()
BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_id BIGINT;
    DECLARE cur CURSOR FOR SELECT AdmissionId FROM studentadmissions
        WHERE IsActive=1 AND IsDeleted=0 AND AdmissionStatus IN ('Approved','Admitted') ORDER BY AdmissionId;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=1;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
    START TRANSACTION;
    -- BEFORE UPDATE creates/links only a real profile for the same unique user.
    UPDATE faculty SET employee_profile_id=NULL
    WHERE employee_profile_id IS NULL AND status=1 AND deleted_at IS NULL;
    OPEN cur;
    admission_loop: LOOP
        FETCH cur INTO v_id;
        IF v_done=1 THEN LEAVE admission_loop; END IF;
        CALL sp_Section_MaterializeAdmissionStudent(v_id);
    END LOOP;
    CLOSE cur;
    COMMIT;
END$$
CALL sp_Section_BackfillAllocationLinks()$$
DROP PROCEDURE sp_Section_BackfillAllocationLinks$$

DROP PROCEDURE IF EXISTS sp_Section_ValidateAllocationSection$$
CREATE PROCEDURE sp_Section_ValidateAllocationSection(IN p_section_id BIGINT)
BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM sections sec
      JOIN colleges c ON c.college_id=sec.college_id AND c.status=1 AND c.deleted_at IS NULL
      JOIN courses co ON co.course_id=sec.course_id AND co.college_id=sec.college_id AND co.status=1 AND co.deleted_at IS NULL
      JOIN branches b ON b.branch_id=sec.branch_id AND b.course_id=sec.course_id AND b.status=1 AND b.deleted_at IS NULL
      JOIN academicyears ay ON ay.academic_year_id=sec.academic_year_id AND ay.deleted_at IS NULL
      JOIN semesters sem ON sem.semester_id=sec.semester_id AND sem.course_id=sec.course_id
       AND sem.branch_id=sec.branch_id AND sem.academic_year_id=sec.academic_year_id AND sem.status=1 AND sem.is_archived=0
      WHERE sec.section_id=p_section_id AND sec.status=1 AND sec.deleted_at IS NULL AND sec.is_archived=0
       AND (sec.semester IS NULL OR sec.semester=sem.semester_number)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active section with valid college/course/branch/year/semester mapping not found.';
    END IF;
END$$

DROP PROCEDURE IF EXISTS sp_Section_GetClassTeacherCandidates$$
CREATE PROCEDURE sp_Section_GetClassTeacherCandidates(IN p_section_id BIGINT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM sections WHERE section_id=p_section_id AND status=1 AND deleted_at IS NULL AND is_archived=0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active section not found.';
    END IF;
    SELECT f.faculty_id AS FacultyId,f.employee_profile_id AS EmployeeProfileId,f.user_id AS UserId,
           f.employee_user_id AS EmployeeUserId,f.full_name AS FullName,f.department_name AS DepartmentName,
           f.designation AS Designation,f.email AS Email,f.mobile AS Mobile
    FROM sections s JOIN vw_section_active_faculty f ON f.college_id=s.college_id
    WHERE s.section_id=p_section_id ORDER BY f.full_name,f.employee_profile_id;
END$$

DROP PROCEDURE IF EXISTS sp_Section_AssignClassTeacher$$
CREATE PROCEDURE sp_Section_AssignClassTeacher(IN p_section_id BIGINT,IN p_employee_profile_id BIGINT,IN p_updated_by BIGINT)
BEGIN
    DECLARE v_college_id BIGINT DEFAULT NULL;
    DECLARE v_profile_id BIGINT DEFAULT NULL;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
    START TRANSACTION;
    SELECT college_id INTO v_college_id FROM sections WHERE section_id=p_section_id
      AND status=1 AND deleted_at IS NULL AND is_archived=0 FOR UPDATE;
    IF v_college_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active section not found.';
    END IF;
    -- Same faculty-to-profile-to-user identity/college predicate as the GET.
    SELECT ep.employee_profile_id INTO v_profile_id
    FROM faculty f JOIN employee_profiles ep ON ep.employee_profile_id=f.employee_profile_id AND ep.user_id=f.user_id
    JOIN users u ON u.user_id=ep.user_id JOIN colleges c ON c.college_id=f.college_id
    WHERE ep.employee_profile_id=p_employee_profile_id AND f.college_id=v_college_id
      AND f.status=1 AND f.deleted_at IS NULL AND ep.status=1 AND ep.deleted_at IS NULL
      AND u.status=1 AND u.deleted_at IS NULL AND (u.college_id IS NULL OR u.college_id=f.college_id)
      AND c.status=1 AND c.deleted_at IS NULL FOR UPDATE;
    IF v_profile_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='EmployeeProfileId must identify active faculty in this section college.';
    END IF;
    UPDATE sections SET class_teacher_employee_profile_id=v_profile_id,updated_by=p_updated_by,updated_at=UTC_TIMESTAMP()
    WHERE section_id=p_section_id;
    COMMIT;
    CALL sp_Section_GetClassTeacher(p_section_id);
END$$

DROP PROCEDURE IF EXISTS sp_Section_GetStudentCandidates$$
CREATE PROCEDURE sp_Section_GetStudentCandidates(IN p_section_id BIGINT,IN p_search VARCHAR(150))
BEGIN
    CALL sp_Section_ValidateAllocationSection(p_section_id);
    SELECT st.student_id AS StudentId,st.admission_id AS AdmissionId,st.student_code AS StudentCode,
           st.full_name AS FullName,st.email AS Email,st.mobile AS Mobile,
           st.college_id AS CollegeId,st.course_id AS CourseId,st.branch_id AS BranchId,st.academic_year_id AS AcademicYearId
    FROM vw_section_student_eligibility st WHERE st.section_id=p_section_id
      AND (p_search IS NULL OR TRIM(p_search)='' OR
           st.student_code COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%',TRIM(p_search),'%') COLLATE utf8mb4_0900_ai_ci OR
           st.full_name COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%',TRIM(p_search),'%') COLLATE utf8mb4_0900_ai_ci)
    ORDER BY st.full_name,st.student_id;
END$$

DROP PROCEDURE IF EXISTS sp_Section_AssignStudents$$
CREATE PROCEDURE sp_Section_AssignStudents(IN p_section_id BIGINT,IN p_student_ids_json JSON,IN p_assigned_by BIGINT)
BEGIN
    DECLARE v_capacity INT DEFAULT NULL;
    DECLARE v_year BIGINT;
    DECLARE v_current INT DEFAULT 0;
    DECLARE v_selected INT DEFAULT 0;
    DECLARE v_valid INT DEFAULT 0;
    DECLARE v_index INT DEFAULT 0;
    DECLARE v_id BIGINT;
    DECLARE v_previous BIGINT DEFAULT 0;
    DECLARE v_locked BIGINT;
    DECLARE v_value JSON;
    DECLARE v_message VARCHAR(128);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        DROP TEMPORARY TABLE IF EXISTS tmp_section_allocation_ids;
        RESIGNAL;
    END;
    IF p_student_ids_json IS NULL OR JSON_TYPE(p_student_ids_json)<>'ARRAY' OR JSON_LENGTH(p_student_ids_json)=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='studentIds must be a non-empty JSON array of positive integer student IDs.';
    END IF;
    IF p_assigned_by IS NULL OR p_assigned_by<=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A valid authenticated assigning user is required.';
    END IF;
    DROP TEMPORARY TABLE IF EXISTS tmp_section_allocation_ids;
    CREATE TEMPORARY TABLE tmp_section_allocation_ids(student_id BIGINT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
    WHILE v_index<JSON_LENGTH(p_student_ids_json) DO
        SET v_value=JSON_EXTRACT(p_student_ids_json,CONCAT('$[',v_index,']'));
        IF JSON_TYPE(v_value)<>'INTEGER' OR CAST(JSON_UNQUOTE(v_value) AS DECIMAL(65,0))<1
            OR CAST(JSON_UNQUOTE(v_value) AS DECIMAL(65,0))>9223372036854775807 THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Every studentIds value must be a positive integer student ID; strings and decimals are invalid.';
        END IF;
        SET v_id=CAST(JSON_UNQUOTE(v_value) AS SIGNED);
        IF EXISTS (SELECT 1 FROM tmp_section_allocation_ids WHERE student_id=v_id) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Duplicate StudentId in the assignment batch.';
        END IF;
        INSERT INTO tmp_section_allocation_ids VALUES(v_id);
        SET v_index=v_index+1;
    END WHILE;
    SET v_selected=v_index;
    -- Fresh validation after waiting for row locks; no pre-lock consistent snapshot.
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    START TRANSACTION;
    SELECT capacity,academic_year_id INTO v_capacity,v_year FROM sections
    WHERE section_id=p_section_id AND status=1 AND deleted_at IS NULL AND is_archived=0 FOR UPDATE;
    IF v_capacity IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active section not found.';
    END IF;
    CALL sp_Section_ValidateAllocationSection(p_section_id);
    -- Lock each actual student in deterministic order, also across different sections.
    student_lock_loop: LOOP
        SELECT MIN(student_id) INTO v_id FROM tmp_section_allocation_ids WHERE student_id>v_previous;
        IF v_id IS NULL THEN LEAVE student_lock_loop; END IF;
        SET v_locked=NULL;
        SELECT student_id INTO v_locked FROM students WHERE student_id=v_id FOR UPDATE;
        IF v_locked IS NULL THEN
            SET v_message=CONCAT('StudentId ',v_id,': student record not found. AdmissionId is not StudentId.');
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=v_message;
        END IF;
        SET v_previous=v_id;
    END LOOP;
    IF EXISTS (SELECT 1 FROM student_section_assignments x JOIN tmp_section_allocation_ids t ON t.student_id=x.student_id WHERE x.status=1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='One or more students already have an active section assignment. No students were moved.';
    END IF;
    -- Separate statements: MySQL cannot reopen a temporary table twice in one query.
    IF EXISTS (SELECT 1 FROM student_sections x JOIN tmp_section_allocation_ids t ON t.student_id=x.student_id WHERE x.is_active=1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='One or more students already have an active legacy section assignment. No students were moved.';
    END IF;
    SELECT COUNT(*) INTO v_valid FROM vw_section_student_eligibility e
      JOIN tmp_section_allocation_ids t ON t.student_id=e.student_id WHERE e.section_id=p_section_id;
    IF v_valid<>v_selected THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Student inactive or college/course/branch/year/known-semester mapping mismatch. No students were assigned.';
    END IF;
    SELECT COUNT(*) INTO v_current FROM student_section_assignments WHERE section_id=p_section_id AND status=1;
    IF v_current+v_selected>v_capacity THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Section capacity exceeded. No students were assigned.';
    END IF;
    INSERT INTO student_section_assignments(student_id,section_id,academic_year_id,status,assigned_at,assigned_by)
    SELECT student_id,p_section_id,v_year,1,UTC_TIMESTAMP(),p_assigned_by FROM tmp_section_allocation_ids ORDER BY student_id;
    COMMIT;
    DROP TEMPORARY TABLE tmp_section_allocation_ids;
    SELECT p_section_id AS SectionId,v_capacity AS Capacity,v_current AS PreviouslyAssigned,
           v_selected AS NewlyAssigned,v_current+v_selected AS TotalAssigned,v_capacity-v_current-v_selected AS AvailableSeats;
END$$

DROP PROCEDURE IF EXISTS sp_Section_GetStudents$$
CREATE PROCEDURE sp_Section_GetStudents(IN p_section_id BIGINT)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM sections WHERE section_id=p_section_id AND deleted_at IS NULL) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Section not found.';
    END IF;
    SELECT x.student_section_assignment_id AS AssignmentId,x.section_id AS SectionId,st.student_id AS StudentId,
           st.student_code AS StudentCode,st.full_name AS FullName,st.email AS Email,st.mobile AS Mobile,
           x.assigned_at AS AssignedAt,x.assigned_by AS AssignedBy
    FROM student_section_assignments x
    JOIN sections sec ON sec.section_id=x.section_id AND sec.deleted_at IS NULL
    JOIN students st ON st.student_id=x.student_id AND st.college_id=sec.college_id AND st.deleted_at IS NULL
    WHERE x.section_id=p_section_id AND x.status=1 ORDER BY st.full_name,st.student_id;
END$$
DELIMITER ;

-- Read-only diagnostics. No sample rows, college repairs or automatic assignments.
SELECT f.faculty_id,f.user_id,f.employee_profile_id,f.college_id,
       CASE WHEN v.faculty_id IS NOT NULL THEN 'ELIGIBLE_FACULTY'
            ELSE 'CHECK_PROFILE_USER_STATUS_AND_COLLEGE' END AS allocation_status
FROM faculty f LEFT JOIN vw_section_active_faculty v ON v.faculty_id=f.faculty_id WHERE f.deleted_at IS NULL;
SELECT a.AdmissionId,a.AdmissionStatus,s.student_id,
       CASE WHEN s.student_id IS NOT NULL THEN 'EXISTING_STUDENT'
            WHEN a.AdmissionStatus NOT IN ('Approved','Admitted') THEN 'NOT_APPROVED_OR_ADMITTED'
            WHEN m.AdmissionId IS NULL THEN 'INCOMPLETE_OR_INCONSISTENT_ACADEMIC_MAPPING'
            ELSE 'STUDENT_CODE_CONFLICT_REQUIRES_REVIEW' END AS allocation_status
FROM studentadmissions a LEFT JOIN students s ON s.admission_id=a.AdmissionId
LEFT JOIN vw_section_admission_mapping m ON m.AdmissionId=a.AdmissionId WHERE a.IsDeleted=0;
